args.CommandLine:
$newCss = @"

/* ========================================================= */
/* PROJECTS REDESIGN (FORTICHE STYLE) */
/* ========================================================= */

.fortiche-projects-board {
    position: relative;
    padding: 20px;
    max-width: 1400px;
    margin: 0 auto;
    display: flex;
    flex-direction: column;
    gap: 80px;
}

.projects-board-header {
    text-align: center;
    margin-bottom: 20px;
    position: relative;
}

.tape-title {
    color: var(--red);
    font-size: 2.5rem;
    display: inline-block;
    background: #111;
    padding: 10px 20px;
    transform: rotate(-1deg);
    box-shadow: 2px 2px 0px var(--red);
    position: relative;
    z-index: 2;
}

.tape-title::before {
    content: '';
    position: absolute;
    top: -10px;
    left: 50%;
    transform: translateX(-50%) rotate(2deg);
    width: 60px;
    height: 20px;
    background: rgba(255,255,255,0.1);
    border: 1px solid rgba(255,255,255,0.2);
    box-shadow: 1px 1px 3px rgba(0,0,0,0.5);
    z-index: 3;
}

.board-subtitle {
    font-family: 'Space Mono', monospace;
    font-size: 0.9rem;
    color: #888;
    margin-top: 15px;
}

.fortiche-section {
    position: relative;
    padding: 40px 20px;
    background: rgba(25, 25, 25, 0.4);
    border: 1px dashed rgba(255,255,255,0.1);
    border-radius: 4px;
}

.section-tag {
    position: absolute;
    top: -20px;
    left: 30px;
    background: var(--red);
    color: #fff;
    padding: 5px 15px;
    font-size: 1.2rem;
    transform: rotate(-2deg);
    box-shadow: 3px 3px 0px rgba(0,0,0,0.5);
    z-index: 10;
}

/* 1. SCRAPBOOK GRID (Zoning) */
.scrapbook-grid {
    display: grid;
    grid-template-columns: 2fr 1fr 1fr;
    grid-template-rows: auto auto;
    gap: 30px;
    align-items: center;
}

.scrapbook-item {
    position: relative;
    transition: transform 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275), z-index 0s;
    cursor: pointer;
}

.scrapbook-item:hover {
    transform: scale(1.05) rotate(0deg) !important;
    z-index: 20;
}

.item-large {
    grid-column: 1 / 2;
    grid-row: 1 / 3;
    transform: rotate(1deg);
}

.item-tilted-right {
    grid-column: 2 / 3;
    transform: rotate(3deg);
}

.item-tilted-left {
    grid-column: 3 / 4;
    transform: rotate(-2deg);
}

.item-tilted-right-more {
    grid-column: 2 / 4;
    transform: rotate(1.5deg);
    margin-top: -20px;
}

.scrapbook-note {
    position: absolute;
    bottom: -15px;
    right: -10px;
    background: #fff;
    color: #000;
    padding: 2px 8px;
    font-size: 0.9rem;
    transform: rotate(-5deg);
    z-index: 5;
    box-shadow: 1px 1px 2px rgba(0,0,0,0.3);
}

/* 2. FILMSTRIP (Plans) */
.blueprint-section {
    padding: 60px 0 !important;
    background: transparent !important;
    border: none !important;
}

.custom-filmstrip .bd-carousel-header {
    display: none; /* Hide old giant headers */
}

.custom-filmstrip .bd-carousel-container {
    width: 100vw;
    margin-left: 50%;
    transform: translateX(-50%);
    background: #111;
    padding: 40px 0;
    border-top: 2px dashed rgba(255,255,255,0.1);
    border-bottom: 2px dashed rgba(255,255,255,0.1);
}

.custom-filmstrip .bd-slide {
    opacity: 0.4;
    transform: scale(0.85);
    transition: all 0.5s ease;
}

.custom-filmstrip .bd-slide.active {
    opacity: 1;
    transform: scale(1);
    z-index: 5;
}

.filmstrip-note {
    position: absolute;
    bottom: 10px;
    left: 20px;
    font-size: 1.1rem;
    color: var(--red);
    text-transform: uppercase;
    letter-spacing: 2px;
    opacity: 0;
    transition: opacity 0.3s;
}

.custom-filmstrip .bd-slide.active .filmstrip-note {
    opacity: 1;
}

/* 3. CUT STACK (Coupes) */
.cut-stack {
    display: flex;
    flex-direction: column;
    gap: 40px;
    margin-top: 30px;
}

.stack-item {
    position: relative;
    width: 85%;
    transition: transform 0.3s ease;
}

.stack-item:nth-child(even) {
    align-self: flex-end;
    transform: rotate(1deg);
}

.stack-item:nth-child(odd) {
    align-self: flex-start;
    transform: rotate(-1deg);
}

.stack-item:hover {
    transform: scale(1.02) rotate(0deg);
    z-index: 5;
}

.stack-note {
    position: absolute;
    top: -15px;
    left: -20px;
    background: #222;
    color: #fff;
    padding: 5px 10px;
    font-size: 1.1rem;
    border: 1px solid var(--red);
    z-index: 5;
}

.stack-item:nth-child(even) .stack-note {
    left: auto;
    right: -20px;
}

/* Responsive */
@media (max-width: 900px) {
    .scrapbook-grid {
        grid-template-columns: 1fr;
        grid-template-rows: auto;
    }
    .item-large, .item-tilted-right, .item-tilted-left, .item-tilted-right-more {
        grid-column: 1 / 2;
        transform: rotate(0);
        margin: 0;
    }
    .stack-item {
        width: 100%;
        align-self: center !important;
        transform: rotate(0) !important;
    }
}
"@

Add-Content -Path 'css/style.css' -Value $newCss -Encoding UTF8
Write-Output "CSS injected."

