ReplacementChunks.ReplacementContent:
/* 3-frame animated border for full-bleed sections */
.fortiche-section {
    position: relative;
    width: 100%;
    padding: 100px 5vw;
    background: var(--bg);
    border: none;
    border-radius: 0;
    margin-top: 0;
}

.fortiche-section.bg-light {
    background: #e0e0e0; /* Gris clair */
    color: #1a1a1a;
}

/* Fix colors for light section */
.fortiche-section.bg-light .bd-carousel-pagination { color: #1a1a1a; }
.fortiche-section.bg-light .bd-carousel-progress { background: rgba(0,0,0,0.1); }
.fortiche-section.bg-light .bd-nav-btn { color: #1a1a1a; background: rgba(255,255,255,0.7); }
.fortiche-section.bg-light .bd-nav-btn:hover { background: #fff; }
.fortiche-section.bg-light .bd-dot { background: rgba(0,0,0,0.3); }
.fortiche-section.bg-light .bd-dot.active { background: #1a1a1a; }
.fortiche-section.bg-light .filmstrip-note { background: rgba(255,255,255,0.8); color: #1a1a1a; }

.shape-divider {
    position: absolute;
    top: 0;
    left: 0;
    width: 100%;
    height: 40px;
    overflow: hidden;
    transform: translateY(-98%); /* Extend upwards */
    pointer-events: none;
    z-index: 5;
}

.shape-divider svg {
    display: block;
    width: 100%;
    height: 100%;
}

.shape-path {
    animation: sketchWobble 0.4s steps(1) infinite;
}

.fortiche-section.bg-light .shape-path { fill: #e0e0e0; }
.fortiche-section:not(.bg-light) .shape-path { fill: var(--bg); }

/* Adjust Section Tag */
.section-tag {
    position: absolute;
    top: -55px; /* Overlaps the divider */
    left: 5vw;
    font-size: 4rem; /* HUGE */
    font-family: var(--font-sketch);
    color: var(--red);
    background: transparent;
    padding: 0;
    box-shadow: none;
    z-index: 10;
    transform: rotate(-2deg);
    pointer-events: none;
    text-shadow: 2px 2px 0px rgba(0,0,0,0.2);
}

ReplacementChunks.TargetContent:
/* 3-frame animated border */
.fortiche-section {
    position: relative;
    padding: 60px 40px;
    background: rgba(25, 25, 25, 0.4);
    border: none;
    border-radius: 4px;
    margin-top: 40px;
}

.animated-border-top {
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 15px;
    overflow: hidden;
    pointer-events: none;
}
.animated-border-bottom {
    position: absolute;
    bottom: 0; left: 0; right: 0;
    height: 15px;
    overflow: hidden;
    pointer-events: none;
}

.sketch-border-path {
    fill: none;
    stroke: rgba(255,255,255,0.2);
    stroke-width: 2;
    animation: sketchWobble 0.4s steps(1) infinite;
}

@keyframes sketchWobble {
    0%, 100% { transform: translate(0, 0); }
    33% { transform: translate(1px, -1px); }
    66% { transform: translate(-1px, 1px); }
}

/* Adjust Section Tag */
.fortiche-section .section-tag {
    top: -15px;
    left: 40px;
    background: var(--bg); /* To hide the line behind it */
    padding: 0 10px;
    z-index: 10;
}
